"""Add Two Numbers II — push digits on stacks so they can be added from the least
significant end without reversing the input lists.

Each new digit is prepended, which builds the result in the right order.

Time: O(n + m)   Space: O(n + m)
"""
if "ListNode" not in globals():
    class ListNode:
        def __init__(self, val=0, next=None):
            self.val = val
            self.next = next


class Solution:
    def addTwoNumbers(self, l1, l2):
        s1, s2 = [], []
        while l1:
            s1.append(l1.val)
            l1 = l1.next
        while l2:
            s2.append(l2.val)
            l2 = l2.next

        head, carry = None, 0
        while s1 or s2 or carry:
            total = carry + (s1.pop() if s1 else 0) + (s2.pop() if s2 else 0)
            carry, digit = divmod(total, 10)
            head = ListNode(digit, head)
        return head
